<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3'; import { computed, watch } from 'vue'; import type { BranchOption, StatementLine, StatusOption, TreasuryAccountOption, TreasuryAdjustmentDetail } from '@/Types/treasury';
const props=defineProps<{branches:BranchOption[];bankAccounts:TreasuryAccountOption[];offsetAccounts:TreasuryAccountOption[];types:StatusOption[];selectedStatementLine:(Pick<StatementLine,'id'|'transaction_date'|'bank_reference'|'description'|'signed_amount'>&{bank_account_id:number;branch_id:number;currency_code:string})|null;defaults:{adjustment_date:string;posting_date:string;currency_code:string;exchange_rate:string};document?:TreasuryAdjustmentDetail}>();
const initialType=props.document?.adjustment_type ?? (props.selectedStatementLine && Number(props.selectedStatementLine.signed_amount)>=0?'bank_interest':'bank_charge');
const form=useForm({branch_id:props.document?.branch_id??props.selectedStatementLine?.branch_id??null as number|null,bank_account_id:props.document?.bank_account_id??props.selectedStatementLine?.bank_account_id??null as number|null,offset_account_id:props.document?.offset_account_id??null as number|null,bank_statement_line_id:props.document?.bank_statement_line_id??props.selectedStatementLine?.id??null as number|null,adjustment_type:initialType,adjustment_date:props.document?.adjustment_date??props.defaults.adjustment_date,posting_date:props.document?.posting_date??props.defaults.posting_date,currency_code:props.document?.currency_code??props.selectedStatementLine?.currency_code??props.defaults.currency_code,exchange_rate:props.document?.exchange_rate??props.defaults.exchange_rate,amount:props.document?.amount??(props.selectedStatementLine?String(Math.abs(Number(props.selectedStatementLine.signed_amount))):''),reference:props.document?.reference??props.selectedStatementLine?.bank_reference??'',description:props.document?.description??props.selectedStatementLine?.description??''});
const availableOffsets = computed(() => {
    if (form.adjustment_type === 'bank_charge') {
        return props.offsetAccounts.filter((account) => account.system_key === 'bank_charges');
    }
    if (form.adjustment_type === 'bank_interest') {
        return props.offsetAccounts.filter((account) => account.system_key === 'bank_interest_income');
    }
    return props.offsetAccounts.filter((account) => !account.system_key);
});
watch(
    () => form.adjustment_type,
    () => {
        const selected = availableOffsets.value.find((account) => account.id === form.offset_account_id);
        if (!selected) form.offset_account_id = availableOffsets.value[0]?.id ?? null;
    },
    { immediate: true },
);
const base=computed(()=>Number(form.amount||0)*Number(form.exchange_rate||0)); const submit=():void=>{if(props.document)form.put(route('treasury-adjustments.update',props.document.id));else form.post(route('treasury-adjustments.store'));};
</script>
<template><form class="space-y-6" @submit.prevent="submit"><div v-if="selectedStatementLine" class="rounded-xl border border-brand-200 bg-brand-50 p-4 text-sm text-brand-800"><b>Statement line #{{selectedStatementLine.id}}</b> · {{selectedStatementLine.transaction_date}} · {{selectedStatementLine.bank_reference??'No reference'}} · {{selectedStatementLine.signed_amount}}<p class="mt-1">{{selectedStatementLine.description}}</p></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Adjustment Details</h2><div class="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4"><label class="space-y-1 text-sm">Branch<select v-model="form.branch_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select><span class="text-xs text-error-500">{{form.errors.branch_id}}</span></label><label class="space-y-1 text-sm">Bank Account<select v-model="form.bank_account_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><span class="text-xs text-error-500">{{form.errors.bank_account_id}}</span></label><label class="space-y-1 text-sm">Adjustment Type<select v-model="form.adjustment_type" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option v-for="t in types" :key="t.value" :value="t.value">{{t.label}}</option></select></label><label class="space-y-1 text-sm">Offset Account<select v-model="form.offset_account_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="a in availableOffsets" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><span class="text-xs text-error-500">{{form.errors.offset_account_id}}</span></label><label class="space-y-1 text-sm">Adjustment Date<input v-model="form.adjustment_date" type="date" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Posting Date<input v-model="form.posting_date" type="date" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Currency<input v-model="form.currency_code" maxlength="3" class="h-11 w-full rounded-lg border px-3 uppercase dark:border-gray-700"/></label><label class="space-y-1 text-sm">Exchange Rate<input v-model="form.exchange_rate" type="number" min="0.00000001" step="0.00000001" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Amount<input v-model="form.amount" type="number" min="0.000001" step="0.000001" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{form.errors.amount}}</span></label><label class="space-y-1 text-sm">Base Amount<input :value="base.toFixed(6)" readonly class="h-11 w-full rounded-lg border bg-gray-50 px-3 dark:border-gray-700 dark:bg-gray-800"/></label><label class="space-y-1 text-sm md:col-span-2">Reference<input v-model="form.reference" maxlength="160" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm md:col-span-2 xl:col-span-4">Description<textarea v-model="form.description" rows="4" maxlength="500" class="w-full rounded-lg border p-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{form.errors.description}}</span></label></div></div><div class="flex justify-end gap-3"><Link :href="document?route('treasury-adjustments.show',document.id):route('treasury-adjustments.index')" class="rounded-lg border px-5 py-2.5 text-sm dark:border-gray-700">Cancel</Link><button :disabled="form.processing" class="rounded-lg bg-brand-500 px-5 py-2.5 text-sm text-white disabled:opacity-50">{{form.processing?'Saving...':document?'Update Draft':'Create Draft'}}</button></div></form></template>
